```python
import bs4
import requests
import re
import json
def task_func(url: str, output_path: str) -> list:
    if not isinstance(url, str) or not url:
        raise ValueError("Input path or URL must be a non-empty string")
    if not isinstance(output_path, str) or not output_path:
        raise ValueError("Output path must be a non-empty string")

    def is_url(s):
        return s.lower().startswith("http://") or s.lower().startswith("https://")

    content = ""
    if is_url(url):
        try:
            resp = requests.get(url, timeout=10)
            resp.raise_for_status()
            content = resp.text
        except requests.RequestException as e:
            raise ConnectionError(f"Failed to retrieve URL content: {e}")
        soup = bs4.BeautifulSoup(content, "html.parser")
        text = soup.get_text(separator=" ")
    else:
        try:
            with open(url, "r", encoding="utf-8") as f:
                content = f.read()
        except OSError as e:
            raise FileNotFoundError(f"Failed to open local file: {e}")
        try:
            soup = bs4.BeautifulSoup(content, "html.parser")
            text = soup.get_text(separator=" ")
        except Exception:
            text = content

    phone_pattern = re.compile(
        r"""
        (?:
            \+?\d{1,3}[\s.-]?
        )?
        (?:
            \(\d{2,4}\)|\d{2,4}
        )
        [\s.-]?
        \d{3,4}
        [\s.-]?
        \d{3,4}
        """,
        re.VERBOSE,
    )

    matches = phone_pattern.findall(text)
    phones = []
    for m in matches:
        p = re.sub(r"\s+", " ", m).strip()
        if p and p not in phones:
            phones.append(p)

    with open(output_path, "w", encoding="utf-8") as out_f:
        json.dump(phones, out_f, ensure_ascii=False, indent=2)

    return phones
